// ===== OTHER PROCESSES =====
SECTIONS.push({id:'otherprocesses',title:'Other Processes',subtitle:'Returns, Material Determination, Make-to-Order',
concepts:[
{name:'Returns Process (RE)',text:'Customer returns goods. Flow: Returns Order (RE) → Return Delivery (goods receipt into returns storage) → Credit Memo (billing reversal). Document flow links all three. VKOA determines credit GL. Returns dont auto-reverse original invoice — separate credit memo.'},
{name:'Credit Memo Request (CR) vs Debit Memo Request (DR)',text:'CR = customer gets money back (price correction downward, quality issue). DR = customer owes more (undercharged). Both create requests that require approval workflow before billing. Not the same as returns — no physical goods movement.'},
{name:'Material Determination / Substitution',text:'System auto-substitutes one material for another when ordered material unavailable. Uses condition records (VB11). Access sequence checks material + customer. Substitution reason documents why. Can be mandatory or optional depending on config.'},
{name:'Make-to-Order (MTO)',text:'Produce against specific SO. Individual customer requirement — stock earmarked for that order. Other orders cannot consume it. Schedule line category F with individual requirement type. Production order linked to specific SO.'},
{name:'Listing / Exclusion',text:'Listing = only listed materials can be sold to a customer. Exclusion = specific materials blocked for a customer. Condition records maintained via VB01. Checked at order entry. Prevents unauthorized product sales.'},
{name:'Down Payment Processing',text:'Customer pays partial amount before delivery. Down payment request created from SO (billing plan). Accounting: down payment posted as special GL. At final invoice: down payment cleared against invoice amount. Balance = remaining payment.'},
],
junior:[
{q:'Returns order document type is?',opts:['OR','RE','CR','DR'],ans:1,exp:'RE = Returns Order. Triggers return delivery (goods receipt) and credit memo billing.'},
{q:'Returns process flow is?',opts:['Returns Order → Invoice','Returns Order → Return Delivery → Credit Memo','Returns Order → Standard Delivery','Credit Memo only'],ans:1,exp:'RE → Return Delivery (goods receipt into returns storage) → Credit Memo (financial reversal).'},
{q:'Credit Memo Request (CR) involves physical goods movement?',opts:['Yes — goods return','No — CR is financial only (price correction). No goods movement','Sometimes','Only for large amounts'],ans:1,exp:'CR = financial correction only. No physical goods return. Returns (RE) involve goods movement.'},
{q:'Material determination substitutes material when?',opts:['Always','When ordered material is unavailable — auto-substitution via condition records','Never automatically','Only at delivery'],ans:1,exp:'Material determination: condition records define substitution rules. System proposes replacement when original unavailable.'},
{q:'MTO individual requirement means stock is?',opts:['Available to anyone','Earmarked for specific SO — other orders cannot consume it','Scrapped','In transit always'],ans:1,exp:'Individual requirement: stock tagged to one SO. Ensures MTO customer gets their specific production run.'},
{q:'Listing means?',opts:['All materials available','Only LISTED materials can be sold to that customer — unlisted materials blocked at order entry','Materials are on sale','Materials are discontinued'],ans:1,exp:'Listing = whitelist. Only materials in the list are allowed. Prevents unauthorized sales.'},
{q:'Down payment is posted as?',opts:['Regular revenue','Special GL indicator — advance payment, not revenue until final invoice','COGS','Inventory'],ans:1,exp:'Down payment = special GL posting. Not revenue. Cleared against final invoice when goods delivered and billed.'},
{q:'Debit Memo Request (DR) means?',opts:['Customer gets refund','Customer owes MORE money (was undercharged)','Customer is blocked','Material returned'],ans:1,exp:'DR = customer was undercharged. Debit memo bills the additional amount. No goods movement.'},
{q:'Exclusion means?',opts:['Customer can buy everything','Specific materials BLOCKED for that customer — cannot be ordered','Materials on sale','Free goods applied'],ans:1,exp:'Exclusion = blacklist. Specific materials cannot be sold to that customer. Checked at order entry.'},
{q:'Returns credit memo uses which GL determination?',opts:['No GL posting','VKOA with returns-specific account keys — can be same or different GL as original invoice','Same GL always','Manual posting'],ans:1,exp:'VKOA determines credit GL. Can use same revenue GL (reversal) or separate returns GL depending on account key config.'},
],
senior:[
{q:'Customer returns goods 6 months later. Pricing on credit memo uses which price?',opts:['Current price','Original order/invoice price — copy control pulls original pricing via document reference','Average of both','Manual entry'],ans:1,exp:'Credit memo references original document. Copy control pulls ORIGINAL pricing. Revenue reversal matches original sale amount.'},
{q:'Material substitution condition record exists but substitution not happening. Diagnosis?',opts:['Bug','Check: (1) material determination procedure assigned to doc type, (2) condition record validity, (3) substitution reason valid, (4) access sequence matches data, (5) original material truly unavailable','Customer master','Pricing issue'],ans:1,exp:'Systematic: procedure assigned? Record valid? Reason configured? Access sequence correct? Also check if substitution is set to mandatory vs optional — optional requires user confirmation.'},
{q:'Client needs returns authorization — customer must get approval number before returning. Config?',opts:['Not possible in standard','Returns order with approval workflow + RMA (Return Material Authorization) number assigned at approval. Incompletion log blocks delivery without RMA','Manual process only','Custom ABAP'],ans:1,exp:'RMA workflow: returns order created → approval workflow triggered → RMA number assigned → only then can return delivery be created. Incompletion log enforces RMA field.'},
{q:'Down payment exceeds order value (customer overpaid). System behavior?',opts:['System blocks','Down payment request can be configured to not exceed order value. If overpayment occurs: excess posted as on-account payment, cleared manually or at next invoice','Auto-refund','Payment rejected'],ans:1,exp:'Config can limit down payment to order value. Overpayment: excess as on-account in FI. Manual clearing or automatic against next invoice.'},
{q:'MTO production complete but customer cancels order. What happens to produced stock?',opts:['Stock is lost','Individual requirement cancelled. Stock becomes unrestricted (available to others) or transferred to MTS. Production costs absorbed unless customer charged cancellation fee','Auto-scrapped','Returns to vendor'],ans:1,exp:'Cancelled MTO: individual stock converts to unrestricted. Decision: sell to another customer, scrap, or charge cancellation fee. Financial: production cost vs recovery.'},
{q:'Client has both material substitution AND free goods for the same material. Processing order?',opts:['Random','Material determination runs FIRST (at order entry), then free goods determination runs at delivery. Two independent processes','Free goods first','Simultaneous'],ans:1,exp:'Sequence: material determination at order entry (substitutes material), then free goods at delivery (determines bonus based on final material). Two separate processes at different stages.'},
{q:'Partial returns — customer returns 30 of 100 units. Multiple original invoices exist. Which invoice does credit memo reference?',opts:['Most recent invoice','User selects which invoice to reference — or system uses FIFO/LIFO based on config. Partial returns need specific document reference','All invoices equally','Random invoice'],ans:1,exp:'User must specify which invoice to reference for partial returns. If config allows, system can auto-select via FIFO. Document reference ensures correct pricing and GL reversal.'},
{q:'Listing/Exclusion with customer hierarchy — parent has exclusion but subsidiary should be exempt. Config?',opts:['Not possible','Maintain listing/exclusion at subsidiary level that overrides parent. Access sequence checks most-specific first (subsidiary before parent)','Delete parent exclusion','Custom ABAP only'],ans:1,exp:'Access sequence hierarchy: subsidiary-level record overrides parent. Maintain explicit "allowed" record at subsidiary level for the excluded material.'},
{q:'Returns with serial number tracking — returned serial must match delivered serial. SAP check?',opts:['No check exists','Serial number profile with "check at returns" flag. System validates returned serial against original delivery serial numbers','Manual verification only','Custom development needed'],ans:1,exp:'Serial number management: return delivery checks serial against outbound delivery. Mismatch flagged. Config: serial number profile with check setting for returns movement type.'},
{q:'Credit memo settlement for rebate agreements — how does this differ from standard credit memo?',opts:['No difference','Rebate credit memo uses rebate-specific billing type, account keys (ERB/ERU), and settles against accrued rebate provision rather than standard revenue reversal','Same billing type','Manual calculation only'],ans:1,exp:'Rebate settlement: specific billing type, accrual account keys (ERB for accrual, ERU for settlement), reverses provision GL rather than standard revenue. Different financial flow from standard credit memo.'},
]});

// ===== LESS FOCUSED TOPICS =====
SECTIONS.push({id:'lessfocused',title:'Less Focused',subtitle:'Rescheduling, Listing/Exclusion, Cross-Selling',
concepts:[
{name:'Rescheduling',text:'Changes delivery date on open schedule lines. Does NOT change order qty. Manual (VA02) or automatic batch job. After PGI: must reverse PGI first, then reschedule, then re-post. Used when delivery dates shift due to production delays or customer request.'},
{name:'Delivery Split',text:'One order line can create multiple deliveries based on: different ship-to partners, different plants, shipping point differences, partial availability. Controlled by delivery group and split criteria config.'},
{name:'Cross-Selling / Up-Selling',text:'System suggests related or upgraded products during order entry. Cross-selling: "customer buying X, also suggest Y." Up-selling: "instead of basic X, suggest premium X+." Uses product proposals and material determination techniques.'},
{name:'Batch Management in SD',text:'Materials tracked by batch (lot number). Batch determination at delivery assigns specific batches. Strategy: FIFO, FEFO (expiry-based), manual. Batch split possible — one order line fulfilled from multiple batches.'},
{name:'Text Determination',text:'Controls which text types appear on documents and how they copy between documents. Text types: header text, item text, packing text. Copy control determines text flow. Configured per doc type and item category.'},
],
junior:[
{q:'Rescheduling changes what?',opts:['Order quantity','Delivery date on open schedule lines — qty stays same','Pricing','Customer master'],ans:1,exp:'Rescheduling = date change only. Quantity remains locked. Can be manual or batch job.'},
{q:'After PGI, can you reschedule?',opts:['Yes directly','No — must reverse PGI first, reschedule, then re-post PGI','Only partial','Only with admin'],ans:1,exp:'PGI locks the delivery. Reverse PGI → change dates → re-post. Three-step process.'},
{q:'Delivery split occurs when?',opts:['Never automatically','When order line has different ship-tos, plants, or partial availability — multiple deliveries created from one line','Only manually','Only for returns'],ans:1,exp:'Auto-split based on: ship-to differences, delivering plant differences, shipping point, partial ATP confirmation.'},
{q:'Cross-selling suggests?',opts:['Discounts','Related or complementary products during order entry','Returns','Credits'],ans:1,exp:'Cross-selling: "buying laptop? Also suggest laptop bag, mouse, warranty." Product proposals at order entry.'},
{q:'Batch determination assigns batches at which stage?',opts:['Order creation','Delivery — batch assigned based on strategy (FIFO, FEFO, manual)','Invoice','Customer master'],ans:1,exp:'Batch determination runs at delivery. Strategy (FIFO = oldest first, FEFO = earliest expiry first) determines which batch.'},
{q:'FIFO batch strategy means?',opts:['Last in, first out','First In, First Out — oldest batch used first','Random selection','Customer selects batch'],ans:1,exp:'FIFO: oldest stock (earliest GR date) used first. Standard for most industries.'},
{q:'FEFO batch strategy is used when?',opts:['Always','For expiry-date-sensitive materials — earliest expiry shipped first','Random','Cost-based'],ans:1,exp:'FEFO: First Expiry, First Out. Critical for pharma, food, chemicals. Prevents expired stock from shipping.'},
{q:'Text determination controls?',opts:['Pricing text','Which text types appear on documents and how they copy between documents','Customer address','Material description'],ans:1,exp:'Text types: header text, item text, packing instructions. Text copy control determines flow between order → delivery → invoice.'},
{q:'One order line fulfilled from multiple batches is called?',opts:['Order split','Batch split — one line, multiple batch assignments at delivery','Delivery merge','Pricing split'],ans:1,exp:'Batch split: delivery line split into sub-items, each with a different batch assignment. Total qty = original line qty.'},
{q:'Delivery group controls?',opts:['Pricing','Which order items are grouped into the same delivery vs split into separate deliveries','Credit check','Output type'],ans:1,exp:'Delivery group: items with same group number combine into one delivery. Different group numbers = separate deliveries.'},
],
senior:[
{q:'Mass rescheduling 500 deliveries after plant shutdown. Approach?',opts:['Manual VA02 each','Batch rescheduling via VL06O (delivery monitor) with plant/date selection, or custom rescheduling report','Cancel all','Not possible'],ans:1,exp:'VL06O delivery monitor with mass processing. Select by plant and date range, bulk reschedule. Custom report for complex criteria.'},
{q:'Batch determination fails — no batch proposed at delivery. Material has batch management active. Diagnosis?',opts:['Material master issue only','Check: (1) batch determination procedure assigned to movement type, (2) batch strategy condition records maintained, (3) batch stock actually exists in that storage location, (4) batch status not restricted','Always manual','System bug'],ans:1,exp:'Systematic: procedure assigned? Strategy records maintained? Stock exists in correct batch status? Storage location correct? Most common: condition records for batch strategy not maintained.'},
{q:'Client wants to prevent delivery creation until all items on the order can be delivered together. Config?',opts:['Not possible','Complete delivery indicator on customer master + delivery group assignment. System waits until all items have full ATP confirmation','Manual check only','Custom ABAP'],ans:1,exp:'Complete delivery indicator: all items must be available before any delivery. Combined with delivery group to define which items must be together.'},
{q:'Cross-selling with automatic item addition — customer orders printer, system auto-adds toner. Config?',opts:['Manual only','Product proposal with automatic item category. Cross-selling condition records trigger auto-addition of related materials','Not possible standard','Custom enhancement only'],ans:1,exp:'Cross-selling via product proposals: condition records link trigger material to proposed material. Auto-addition possible with appropriate item category and product proposal type.'},
{q:'Batch recall scenario — specific batch found defective, need to identify all customers who received it. How?',opts:['Manual records','Batch where-used report (MB56) + delivery batch tracing. System tracks batch → delivery → customer linkage','Not possible in standard','Only with QM module'],ans:1,exp:'Batch traceability: MB56 (batch where-used), delivery documents with batch assignment, customer linkage via document flow. Forward and backward tracing standard functionality.'},
{q:'Text from sales order should copy to delivery but NOT to invoice. Configuration?',opts:['Not possible to control per document','Text copy control: configure text ID copy rules between doc types. Set copy from order→delivery but NOT delivery→invoice for that text type','All or nothing','Custom ABAP only'],ans:1,exp:'Text copy control: per text ID, configure which document transitions copy the text. Granular control: copy to delivery yes, copy to invoice no.'},
{q:'Client has seasonal rescheduling — all December deliveries must move to January. Automated approach?',opts:['Manual VA02','Selection report: select all open deliveries with December dates, mass-update to January. Use BAPI_DELIVERY_CHANGE or VL06O mass processing','Not possible','Cancel and recreate'],ans:1,exp:'Mass rescheduling via BAPI or VL06O with date range selection. Can also use LSMW for bulk date changes. Document change history maintained for audit.'},
{q:'Batch split at delivery creates pricing implications. Why?',opts:['No pricing impact','Each batch sub-item can have different batch-specific pricing (e.g., different cost, different quality grade). Pricing procedure must handle batch-level conditions','Only affects COGS','Only affects output'],ans:1,exp:'Batch-specific pricing: different batches may have different costs or quality-grade-based pricing. Condition records at batch level. Pricing procedure must include batch-relevant condition types.'},
{q:'Up-selling: customer orders basic model, system should suggest premium. Difference from material substitution?',opts:['Same thing','Up-selling = suggestion (customer chooses). Material substitution = automatic replacement. Different processes — up-sell uses product proposals, substitution uses material determination','Only terminology','Only pricing differs'],ans:1,exp:'Up-selling: optional suggestion via product proposals. Customer decides. Material substitution: automatic replacement when original unavailable. Different mechanisms and customer experience.'},
{q:'Delivery split causes multiple invoices for one order. Customer wants one consolidated invoice. Reconciliation?',opts:['Not possible','Collective billing (VF04) with billing date calendar. Multiple deliveries → one consolidated invoice per billing period','Manual merge','Separate credit/debit'],ans:1,exp:'Collective billing: VF04 run combines multiple deliveries into one invoice per customer per billing period. Customer master billing date calendar controls frequency.'},
]});
// ===== ASAP & AGILE =====
SECTIONS.push({id:'asapagile',title:'ASAP & Agile',subtitle:'Implementation Methodologies',
concepts:[
{name:'ASAP Methodology (Accelerated SAP)',text:'SAP standard implementation framework. 5 phases: (1) Project Preparation (scope, team, budget), (2) Business Blueprint (AS-IS/TO-BE gap analysis, requirements), (3) Realization (configuration, development, unit testing), (4) Final Preparation (integration testing, user training, data migration, cutover), (5) Go-Live & Support.'},
{name:'Business Blueprint (BBP)',text:'Most critical phase. Documents AS-IS processes, designs TO-BE processes in SAP. Identifies gaps between business requirements and SAP standard. Gap = either configure, customize (ABAP), or change business process. Sign-off required before Realization.'},
{name:'Realization Phase',text:'Two work streams: Baseline (configure standard SAP per BBP) and Final (develop custom enhancements, reports, interfaces, forms — RICEFW objects). Unit testing per object. Iterative cycles within this phase.'},
{name:'SAP Activate Methodology',text:'Replaces ASAP for S/4HANA and cloud implementations. 6 phases: Discover → Prepare → Explore → Realize → Deploy → Run. Emphasizes Fit-to-Standard (use SAP standard, minimize custom). Incorporates agile practices.'},
{name:'Agile in SAP Projects',text:'Scrum sprints (2-4 weeks) within Realization phase. Product backlog = RICEFW objects. Sprint planning, daily standups, sprint review with business. Not pure Agile — hybrid with ASAP/Activate governance. Common in S/4HANA implementations.'},
{name:'Fit-to-Standard Workshop',text:'S/4HANA approach: demonstrate standard SAP processes to business, identify gaps only where standard truly cannot work. Reduces customization. Shift from "build what business wants" to "adopt what SAP provides, customize only when essential."'},
{name:'RICEFW Objects',text:'Reports, Interfaces, Conversions, Enhancements, Forms, Workflows. The custom development objects in any SAP implementation. Each requires functional spec, technical spec, development, unit test, integration test. Quantity drives project effort and cost.'},
],
junior:[
{q:'ASAP has how many phases?',opts:['3','4','5','6'],ans:2,exp:'5 phases: Project Preparation, Business Blueprint, Realization, Final Preparation, Go-Live & Support.'},
{q:'Business Blueprint phase focuses on?',opts:['Coding','AS-IS/TO-BE analysis and gap identification','Go-live cutover','User training only'],ans:1,exp:'BBP: document current processes, design SAP processes, identify gaps. Most critical phase — errors here cascade through the project.'},
{q:'RICEFW stands for?',opts:['Requirements, Implementation, Configuration, Enhancement, Forms, Workflows','Reports, Interfaces, Conversions, Enhancements, Forms, Workflows','Random acronym','Risk, Integration, Cost, Effort, Function, Work'],ans:1,exp:'RICEFW: the six categories of custom development objects in SAP implementations.'},
{q:'SAP Activate replaces ASAP for?',opts:['ECC implementations','S/4HANA and cloud implementations','Only on-premise','Legacy systems only'],ans:1,exp:'Activate = modern methodology for S/4HANA (on-premise and cloud). Incorporates agile and Fit-to-Standard.'},
{q:'Fit-to-Standard means?',opts:['Build everything custom','Adopt SAP standard processes, customize only when essential','Fit SAP to legacy','Standard reporting only'],ans:1,exp:'Fit-to-Standard: use SAP standard, minimize custom development. Demonstrate standard → identify true gaps → customize only what is essential.'},
{q:'Realization phase has which two work streams?',opts:['Design and Test','Baseline (standard config) and Final (custom RICEFW development)','Planning and Execution','AS-IS and TO-BE'],ans:1,exp:'Baseline: configure standard SAP per BBP. Final: develop custom enhancements, reports, interfaces, forms (RICEFW objects).'},
{q:'Sprint duration in SAP Agile projects is typically?',opts:['1 day','2-4 weeks','6 months','1 year'],ans:1,exp:'2-4 week sprints within Realization. Product backlog = RICEFW objects and configuration items.'},
{q:'SAP Activate has how many phases?',opts:['4','5','6 (Discover, Prepare, Explore, Realize, Deploy, Run)','7','3'],ans:2,exp:'6 phases: Discover → Prepare → Explore → Realize → Deploy → Run.'},
{q:'In hybrid Agile-ASAP, which phases use Agile sprints?',opts:['All phases equally','Primarily Realization phase — sprints for configuration and development','Only Blueprint','Only Go-Live'],ans:1,exp:'Agile sprints fit best in Realization. Blueprint and Go-Live phases need more waterfall governance (sign-offs, cutover plans).'},
{q:'Gap analysis identifies?',opts:['Budget overruns','Differences between business requirements and SAP standard functionality','User satisfaction','Server capacity'],ans:1,exp:'Gap = business needs something SAP doesnt provide out of the box. Resolution: configure, develop custom (RICEFW), or change business process.'},
],
senior:[
{q:'Client insists on 50+ custom RICEFW objects. As Senior Manager, your recommendation?',opts:['Build them all','Challenge each: Fit-to-Standard review to eliminate unnecessary customization. Custom objects = ongoing maintenance cost, upgrade risk, testing burden. Target: reduce by 40-60% via process change','Refuse all','Build only reports'],ans:1,exp:'Senior Manager role: governance over customization scope. Each RICEFW object = lifecycle cost. Challenge justification, propose standard alternatives, get business sign-off on total cost of ownership.'},
{q:'BBP sign-off delayed by 3 months due to business disagreements. Impact and action?',opts:['No impact','Critical: delays cascade to Realization and Go-Live. Action: escalate to steering committee, propose phased BBP (core processes first, enhancements later), set deadline with executive sponsor','Wait patiently','Skip BBP'],ans:1,exp:'BBP delay = project delay. Escalation path: steering committee, executive sponsor. Phased approach: agree on core 80%, defer edge cases. Never skip BBP — it creates rework in Realization.'},
{q:'Activate Explore phase vs ASAP Blueprint — key difference?',opts:['Same thing different name','Explore uses Fit-to-Standard workshops (demo standard SAP, identify gaps) vs Blueprint which documents AS-IS first. Explore starts from SAP standard, Blueprint starts from business current state','Only duration differs','Only tools differ'],ans:1,exp:'Fundamental shift: ASAP BBP = "tell me your process, Ill build it in SAP." Activate Explore = "let me show you SAP standard, tell me where it doesnt work." Starting point is different — reduces customization.'},
{q:'Data migration strategy — which phase should planning start?',opts:['Final Preparation only','Blueprint/Explore — migration planning starts early. Data quality assessment, cleansing rules, mapping, mock runs all before cutover','Realization only','Go-Live weekend'],ans:1,exp:'Data migration planning starts in BBP/Explore: assess data quality, define cleansing rules, create mapping documents. Mock migration runs in Realization. Final run in cutover. Late planning = go-live risk.'},
{q:'Client wants "pure Agile" for S/4HANA implementation. Your response?',opts:['Agree fully','Challenge: pure Agile doesnt work for ERP implementations. Regulatory/compliance sign-offs, data migration cutover, integration testing need waterfall governance. Recommend hybrid: Agile sprints within Activate framework','Refuse Agile entirely','Only waterfall'],ans:1,exp:'Hybrid approach: Agile sprints for iterative config/dev, waterfall governance for compliance sign-offs, data migration, integration testing, cutover planning. Pure Agile lacks the governance ERP implementations need.'},
{q:'Cutover planning — what does a Senior Manager ensure?',opts:['Just go-live date','Full cutover plan: data freeze dates, migration sequence, fallback plan, hypercare team, communication plan, go/no-go criteria, dress rehearsal results','Only data migration','Only user training'],ans:1,exp:'Cutover = orchestrated event. Data freeze, migration sequence, system availability, fallback/rollback plan, go/no-go criteria (tested in dress rehearsal), hypercare team on standby, business communication.'},
{q:'Post-go-live hypercare duration and scope?',opts:['1 day','Typically 4-8 weeks. Dedicated support team, daily issue triage, priority bug fixing, business stabilization. Transition to steady-state support when KPIs normalize','1 year','No hypercare needed'],ans:1,exp:'Hypercare: 4-8 weeks post-go-live. Enhanced support staffing, daily triage meetings, rapid issue resolution. Exit criteria: critical incident count below threshold, process KPIs stable.'},
{q:'S/4HANA greenfield vs brownfield — when does each apply?',opts:['Always greenfield','Greenfield: clean start, new config, data migration only (new company or major process redesign). Brownfield: system conversion, keep existing config/data (minimal process change). Hybrid: selective data migration','Always brownfield','No difference'],ans:1,exp:'Greenfield: clean slate, best for major transformation. Brownfield: conversion, keeps customizations (risky if heavy custom). Selective data transition: middle ground. Decision based on customization debt, business transformation goals, timeline.'},
{q:'Testing strategy across ASAP phases — what goes where?',opts:['All testing in Final Preparation','Unit Test (Realization) → Integration Test (late Realization/Final Prep) → UAT (Final Prep) → Performance Test → Regression Test → Cutover Dress Rehearsal','Only UAT matters','Testing is optional'],ans:1,exp:'Testing pyramid: unit (per object), integration (cross-process), UAT (business validates), performance (load), regression (ensure no breakage), dress rehearsal (simulate cutover). Each phase has specific testing scope.'},
{q:'Client asks: "Why cant we just configure SAP without a methodology?" Your answer?',opts:['They can','Without methodology: no scope control (creep), no sign-offs (rework), no testing strategy (production bugs), no change management (user rejection), no data migration plan (data quality disasters). Methodology = risk management framework','Methodology is optional','Only large projects need it'],ans:1,exp:'Methodology provides: scope governance, quality gates, risk management, change control, testing framework, stakeholder alignment. Without it: uncontrolled scope, untested config, surprised users, data issues at go-live.'},
]});

// ===== PUBLIC CLOUD =====
SECTIONS.push({id:'publiccloud',title:'Public Cloud',subtitle:'S/4HANA Cloud & SaaS Architecture',
concepts:[
{name:'S/4HANA Deployment Options',text:'Three models: (1) Public Cloud (multi-tenant SaaS, quarterly updates, limited customization), (2) Private Cloud (single-tenant, managed by SAP or hyperscaler, more customization), (3) On-Premise (full control, full customization, self-managed infrastructure).'},
{name:'Public Cloud — Key Constraints',text:'No custom ABAP (only key user extensibility and side-by-side extensions via BTP). Quarterly mandatory updates. Fit-to-Standard mandatory. No modification of SAP standard code. Limited access to database layer. SAP manages infrastructure, upgrades, security.'},
{name:'Key User Extensibility',text:'In-app extensions without ABAP: custom fields (add fields to standard screens/tables), custom logic (BAdIs for business rules), custom CDS views (reporting), custom communication scenarios (integration). All upgrade-safe — SAP guarantees compatibility.'},
{name:'SAP BTP (Business Technology Platform)',text:'Side-by-side extension platform. For logic that CANNOT run in Public Cloud core: complex integrations, custom UIs (Fiori), advanced analytics, AI/ML, workflow. Connects to S/4HANA via APIs. Cloud-native development (CAP, Node.js, Java).'},
{name:'Clean Core Principle',text:'S/4HANA philosophy: keep the core system "clean" — no modifications, no custom code in core. All extensions either in-app (key user extensibility) or side-by-side (BTP). Enables smooth quarterly updates. Opposite of ECC approach where custom code was embedded.'},
{name:'SD in Public Cloud',text:'Standard SD processes available. Key differences from on-premise: no custom pricing routines (use standard or BAdI), no custom copy control routines (use standard), limited output customization (use Output Management with BRF+). Fiori apps replace SAP GUI transactions.'},
],
junior:[
{q:'S/4HANA Public Cloud is?',opts:['Self-managed server','Multi-tenant SaaS — SAP manages infrastructure, quarterly updates mandatory','Single-tenant only','Same as on-premise'],ans:1,exp:'Public Cloud: multi-tenant SaaS. SAP manages everything. Quarterly updates. Fit-to-Standard required.'},
{q:'Can you write custom ABAP in Public Cloud?',opts:['Yes — full ABAP','No — only key user extensibility and BTP side-by-side extensions','Only with SAP approval','Only for reports'],ans:1,exp:'No custom ABAP in core. Key user extensibility (in-app) or BTP (side-by-side) for extensions. All upgrade-safe.'},
{q:'Key user extensibility includes?',opts:['Full ABAP development','Custom fields, custom logic (BAdIs), custom CDS views, custom communication scenarios','Only reports','Only forms'],ans:1,exp:'In-app extensions without ABAP: custom fields, BAdI logic, CDS views, communication scenarios. Upgrade-safe.'},
{q:'SAP BTP is used for?',opts:['Core SD processing','Side-by-side extensions that cannot run in Public Cloud core — complex integrations, custom UIs, analytics','Database management','Infrastructure only'],ans:1,exp:'BTP = extension platform outside S/4HANA core. For complex logic, custom Fiori apps, integrations, AI/ML.'},
{q:'Clean Core means?',opts:['Regular system cleanup','No modifications to SAP standard code — all extensions are in-app or side-by-side, enabling smooth updates','Clean database','Clean master data'],ans:1,exp:'Clean Core: zero modifications to SAP code. Extensions are either in-app (key user) or on BTP. Enables quarterly updates without regression.'},
{q:'Public Cloud updates happen?',opts:['Never','Quarterly — mandatory, managed by SAP','Annually','Only when customer requests'],ans:1,exp:'Quarterly mandatory updates. SAP manages the upgrade. Customer must test key user extensions for compatibility.'},
{q:'SD in Public Cloud uses which UI?',opts:['SAP GUI only','Fiori apps — browser-based, responsive, role-based','Custom desktop app','No UI — API only'],ans:1,exp:'Fiori apps replace SAP GUI. Browser-based, mobile-responsive, role-based launchpad.'},
{q:'Private Cloud vs Public Cloud — key difference?',opts:['Same thing','Private = single-tenant, more customization allowed, customer-specific upgrade schedule. Public = multi-tenant, limited customization, mandatory quarterly updates','Only pricing differs','Only location differs'],ans:1,exp:'Private: single-tenant, more customization, flexible upgrade schedule. Public: multi-tenant SaaS, strict Fit-to-Standard, quarterly mandatory updates.'},
{q:'Fit-to-Standard in Public Cloud means?',opts:['Custom everything','Adopt SAP standard processes. Customize only via supported extensibility (key user, BTP). No modifications to core','Standard reporting','Standard forms only'],ans:1,exp:'Fit-to-Standard: use SAP as-is. If gap exists: key user extensibility or BTP extension. No ABAP modifications.'},
{q:'On-premise S/4HANA allows?',opts:['Same as Public Cloud','Full customization — custom ABAP, modifications, full database access, self-managed upgrades','Only standard features','Less than cloud'],ans:1,exp:'On-premise: full control. Custom ABAP, code modifications, database access, upgrade on your schedule. Maximum flexibility, maximum maintenance responsibility.'},
],
senior:[
{q:'Client has 200 custom ABAP reports in ECC. Moving to Public Cloud. Strategy?',opts:['Migrate all reports','Classify: (1) eliminate obsolete, (2) replace with standard Fiori/CDS views, (3) rebuild essential ones as BTP apps or Embedded Analytics. Target: 80%+ eliminated or replaced','Keep all in custom','Not possible to move'],ans:1,exp:'200 custom reports = migration challenge. Classify by business value: most can be replaced by standard analytics/CDS views. Essential ones → BTP or Embedded Analytics. Clean core requires this discipline.'},
{q:'Custom pricing routine in ECC (VOFM) wont work in Public Cloud. Alternative?',opts:['Not possible','Standard BAdI for pricing enhancement — SAP provides specific BAdIs for pricing logic. If insufficient: BTP side-by-side service called from pricing via API','Stay on-premise','Remove custom pricing'],ans:1,exp:'Public Cloud pricing: standard BAdIs replace custom VOFM. If logic is complex: BTP microservice called via API during pricing. Requires architecture redesign but maintains clean core.'},
{q:'Quarterly update breaks a key user extension. Responsibility and resolution?',opts:['SAP fixes it','Customer responsibility — key user extensions are upgrade-safe by design, but custom logic may need adjustment. Test in sandbox before update activates in production','Ignore the break','Roll back update'],ans:1,exp:'Key user extensions are upgrade-safe (framework guaranteed), but custom BAdI logic may need adjustment if SAP changes underlying data model. Test in sandbox pre-update. SAP provides release notes for breaking changes.'},
{q:'Client needs complex partner determination logic not available in standard Public Cloud. Approach?',opts:['Not possible','(1) Check if standard partner determination covers 80%, (2) Key user BAdI for simple extensions, (3) BTP side-by-side service for complex logic called via API. Evaluate effort vs business value','Switch to on-premise','Manual partner entry'],ans:1,exp:'Tiered approach: standard first (covers most), BAdI for simple gaps, BTP for complex. Always evaluate: is the complexity worth the extension cost, or can the process be simplified?'},
{q:'Integration pattern: Public Cloud S/4HANA ↔ legacy on-premise system. Architecture?',opts:['Direct database link','API-based integration via SAP BTP Integration Suite (middleware). S/4HANA exposes standard APIs, BTP handles transformation/routing, legacy system connects via adapter','File transfer only','Manual data entry'],ans:1,exp:'No direct database access in Public Cloud. Integration Suite on BTP: S/4HANA APIs → BTP Integration Suite (transformation, routing, error handling) → legacy system adapter. Event-driven or scheduled batch patterns.'},
{q:'Client asks: "Why not Private Cloud instead of Public?" When is Private Cloud the right choice?',opts:['Always prefer Public','Private when: (1) regulatory requires data isolation, (2) heavy existing customizations need migration path, (3) industry-specific processes not in Public standard, (4) upgrade timing flexibility needed for seasonal businesses','Never — always Private','Cost is the only factor'],ans:1,exp:'Private Cloud: data sovereignty requirements, heavy customization legacy, industry-specific needs, upgrade timing control. Public Cloud: greenfield, standard processes, fastest time-to-value, lowest TCO.'},
{q:'Embedded Analytics in Public Cloud replaces what from on-premise?',opts:['Nothing','Custom ABAP reports, SAP Query, classic BW reporting. CDS-based analytical views embedded in Fiori — real-time, no separate BW needed for operational reporting','Only dashboards','Only financial reports'],ans:1,exp:'Embedded Analytics: CDS analytical views power Fiori analytical apps. Replace custom ABAP reports and much of operational BW reporting. Real-time, in-system. BW still needed for cross-system/historical analytics.'},
{q:'Clean Core assessment for ECC → S/4HANA Public Cloud migration — what does it evaluate?',opts:['Only code quality','Custom code inventory (volume, usage, criticality), modification analysis (SAP note conflicts), interface inventory, custom form/output assessment, data model extensions — produces remediation roadmap','Only data volume','Only user count'],ans:1,exp:'Clean Core assessment: scan all custom objects, classify by criticality and usage, identify SAP note conflicts, assess interfaces and outputs. Output: remediation roadmap with retire/replace/rebuild decisions.'},
{q:'Client wants to use SAP GUI alongside Fiori in Public Cloud. Possible?',opts:['Yes — both available','No — Public Cloud is Fiori-only. SAP GUI not available. All transactions via Fiori apps or APIs','Only for admin','Only during migration'],ans:1,exp:'Public Cloud: Fiori only. SAP GUI not available. This is a significant change management point for users accustomed to SAP GUI. Training budget must account for this.'},
{q:'Two-tier ERP strategy: headquarters on S/4HANA Private Cloud, subsidiaries on Public Cloud. SD implications?',opts:['No implications','IC processes between tiers need API-based integration. Master data harmonization critical. Subsidiaries follow Fit-to-Standard, HQ has more customization. Transfer pricing via integration, not direct IC billing','Same system for all','Not possible'],ans:1,exp:'Two-tier: different customization levels per tier. IC between tiers = API integration (not native IC billing). Master data governance across tiers essential. Common for global enterprises with diverse subsidiary needs.'},
]});

