export const ADVANCED = [
{q:'IC pricing: Entity A bills B at ₹1200, B records cost at ₹1100. Valid?',opts:['Error — must match','Valid — IC pricing can differ per entity costing rules','Only with manual override','System blocks this'],ans:1,exp:'IC transfer price (A→B) and local cost booking (B) can legitimately differ due to separate costing views, currency conversion, or transfer pricing method.'},
{q:'Free goods condition record exists but free goods not on delivery. Why?',opts:['Free goods copy from order','Free goods RE-DETERMINED at delivery — check delivery-level determination config','Always a system bug','Pricing blocks free goods'],ans:1,exp:'Free goods determined dynamically at delivery, not copied from order. Check: delivery-level determination active, record validity, minimum qty threshold.'},
{q:'Incompletion log shows complete but order has yellow status. Cause?',opts:['Incompletion covers only mandatory fields. Yellow = credit block, delivery block, or other business warnings','Always means incomplete','System error','Customer master issue'],ans:0,exp:'Incompletion checks mandatory fields only. Yellow status can come from credit blocks, delivery blocks, or other warnings separate from field completeness.'},
{q:'Returns 3 months after sale. Price changed since. Which price on credit memo?',opts:['Current market price','Original order/invoice price — copy control pulls original pricing','Average of both','Manual entry required'],ans:1,exp:'Credit memo references original document via copy control. Original pricing preserved for accurate revenue reversal.'},
{q:'Credit check passes at order but blocks at delivery for same customer/amount. Why?',opts:['System error','Between order and delivery: other orders consumed credit, payments not posted, or exchange rate changed','Config changed','Customer updated'],ans:1,exp:'Credit exposure is dynamic. Other orders, missing payments, or exchange rate movement between check points cause different results.'},
{q:'Backorder: SO 100, delivered 70, customer cancels remaining 30. Order status?',opts:['Remains open','Fully processed — 70 delivered + 30 rejected = 100 total accounted','Partially delivered forever','Cancelled entirely'],ans:1,exp:'Rejecting remaining qty changes those items to rejected. Order fully processed: delivered qty + rejected qty = total qty.'},
{q:'Field correct on order but wrong on invoice. Delivery shows wrong value too. Where did it break?',opts:['Invoice has own determination','Copy control order→delivery (VTLA) changed or dropped the field value','Order was wrong','Customer master changed'],ans:1,exp:'Invoice copies from delivery. If field wrong on delivery, issue is in VTLA (order→delivery copy control). Check field-level copy rules.'},
{q:'Manual PR00 override (100→90) on order. Invoice shows 100. Root cause?',opts:['Overrides dont save','Copy control pricing type G/H redetermines from records — manual overrides lost','System bug','Tax recalculation'],ans:1,exp:'Pricing type G/H re-reads condition records at billing. Manual overrides lost. Use pricing type B to preserve manual changes.'},
{q:'Delivery qty changed from 100 to 80 AFTER PGI. Possible?',opts:['Yes directly','No — must reverse PGI first, change delivery, then re-post PGI','Automatic adjustment','Supervisor override'],ans:1,exp:'After PGI: goods posted to accounting. Must reverse PGI → change qty → re-post. Cannot modify without reversing movement.'},
{q:'Consignment Fill-Up vs Issue — key difference?',opts:['Same process','Fill-up = stock TO customer (no invoice, ownership stays). Issue = customer USES stock (invoice triggered, ownership transfers)','Fill-up is returns','Issue is always free'],ans:1,exp:'CF: move stock, no billing, no ownership transfer. CI: consumption, invoice, ownership transfer, revenue recognition.'},
{q:'Condition record at Cust+Mat level AND at Customer level. Which wins?',opts:['Customer level','Cust+Mat — access sequence checks most-specific first. First hit wins','Both apply','Random'],ans:1,exp:'Hierarchical: most-specific (Cust+Mat) checked first. If found, search stops. First-hit-wins principle.'},
{q:'STO within same Company Code — is IC billing needed?',opts:['Always','No — same legal entity. Pure MM stock transfer. No billing, no revenue/COGS','Depends on plant','Only cross-country'],ans:1,exp:'Same CC = same entity. STO is logistics only. IC billing only needed when plants are in DIFFERENT Company Codes.'},
{q:'Partner determination finds Ship-to but no Payer. Order behavior?',opts:['Saves without Payer','Error — Payer mandatory in standard partner determination. Order cant save or incompletion blocks next step','System assigns default','Billing blocked only'],ans:1,exp:'Standard: Payer is mandatory. Missing Payer = incompletion log error. Blocks order save or next step depending on config.'},
{q:'Customer hierarchy pricing: parent has 10% discount, subsidiary orders, discount missing. First check?',opts:['Pricing procedure','Access sequence for discount must include hierarchy node fields. Condition record at hierarchy level. Hierarchy assignment in VDH1N','Customer master','Material pricing'],ans:1,exp:'Hierarchy pricing needs: hierarchy assigned, access sequence includes hierarchy fields, condition records at node level. Most common miss: access sequence.'},
{q:'Billing plan milestone: 30% at order, 30% at delivery, 40% at go-live. Where configured?',opts:['Pricing procedure','Item category (billing plan type) + billing plan dates/amounts on sales order item','Copy control','Output determination'],ans:1,exp:'Billing plan type assigned to item category. Milestone dates and percentages maintained on the order item.'},
{q:'Returns order created but delivery blocked — "no stock in returns storage location." Why?',opts:['Wrong order type','Returns delivery needs returns-specific storage location configured in delivery type settings','Customer issue','Material blocked'],ans:1,exp:'Returns delivery: specific movement type + storage location for returned goods. If storage location not configured in delivery type, delivery fails.'},
{q:'Batch determination: no batch proposed despite batch management active. Cause?',opts:['Material master only','Check: batch determination procedure assigned, strategy condition records maintained, batch stock exists, batch status not restricted','Always manual','System limitation'],ans:1,exp:'Procedure assigned? Strategy records maintained? Stock in correct batch? Status unrestricted? Most common: missing strategy condition records.'},
{q:'Output dispatch time 2 (batch) — outputs stuck "not processed" for days. Fix?',opts:['Recreate outputs','Schedule background job RSNAST00. Outputs with batch dispatch need this job running periodically','System restart','Manual processing only'],ans:1,exp:'Dispatch time 2 = batch processing via RSNAST00. If job not scheduled, outputs accumulate unprocessed. Most common output issue.'},
{q:'Statistical condition type in pricing — calculated but value shown as zero in net price. Normal?',opts:['Error','Yes — statistical conditions are calculated and displayed but NOT added to net price. For reporting/costing only','Should be included','Pricing bug'],ans:0,exp:'Statistical: calculated, displayed, but excluded from net price total. Used for internal cost estimates, commission tracking, margin analysis.'},
{q:'S/4HANA advanced ATP (aATP) gives different results than ECC classic ATP. Same master data. Why?',opts:['Identical results expected','aATP has rule-based substitution, backorder prioritization, product allocation integration, alternative confirmation — architecturally different from classic','Migration error','Network issue'],ans:1,exp:'aATP is architecturally different: BOP reallocates by priority, rules can substitute materials/locations, product allocation integrated. Legitimately different (usually more accurate) results.'},
];

